fd.rendered(function() {

    fd.field('AgreementDate').disabled = true;
    fd.field('SignatoryName').disabled = true;
    if (!fd.field('AgreementDate').value) fd.field('AgreementDate').value = new Date();
    var previousClientName = '';
    var previousRepresentativeName = '';
    var copiedSignerName = '';
    var copiedBillingAddress = '';

    function copyIfUntouched(targetName, value, previousCopy) {
        var target = fd.field(targetName);
        if (!target.value || target.value === previousCopy) target.value = value || null;
        return value || '';
    }
    function syncSigner() {
        var useRepresentative = fd.field('HasRepresentative').value === true;
        var value = useRepresentative ? fd.field('RepresentativeName').value : fd.field('ClientFullName').value;
        copiedSignerName = copyIfUntouched('SignatoryName', value, copiedSignerName);
    }
    function syncBillingAddress() {
        if (fd.field('FundingSource').value !== 'Self-funded') return;
        copiedBillingAddress = copyIfUntouched('BillingAddress', fd.field('ClientAddress').value, copiedBillingAddress);
    }
    fd.field('ClientFullName').$on('change', function(value) { previousClientName = value || ''; syncSigner(); });
    fd.field('RepresentativeName').$on('change', function(value) { previousRepresentativeName = value || ''; syncSigner(); });
    fd.field('HasRepresentative').$on('change', syncSigner);
    fd.field('ClientAddress').$on('change', syncBillingAddress);
    fd.field('FundingSource').$on('change', syncBillingAddress);
    if (!fd.field('AgreementDate').value) fd.field('AgreementDate').value = new Date();
    syncSigner(); syncBillingAddress();
});
